'use strict';
const $=id=>document.getElementById(id),svg=$('map'),NS='http://www.w3.org/2000/svg';
let world,detail=3,worker,seed=Number(new URLSearchParams(location.search).get('seed'))||43,run=null,playing=false,time=0,lastTime=0,mode='setup',dynamic,view=[-20,-560,580,580],tracks={},selection=null;
function el(tag,attrs={},parent=svg){const n=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))n.setAttribute(k,v);parent.append(n);return n;}
function poly(points,fill,stroke='none',width=0,parent=svg){return el('polygon',{points:points.map(p=>`${p[0]},${-p[1]}`).join(' '),fill,stroke,'stroke-width':width},parent);}
function txt(x,y,text,size=4,parent=svg,attrs={}){const n=el('text',{x,y:-y,'font-size':size,...attrs},parent);n.textContent=text;return n;}
let artDefs=()=>el('defs'),tree=()=>{};
function workerStart(){if(worker)worker.terminate();worker=new Worker('/simulation-worker.js?v=1');worker.onmessage=({data:d})=>{if(d.type==='territory'){world=d.world;land();$('run').disabled=false;$('new').disabled=false;$('notice').textContent='';}if(d.type==='progress'){$('progress-text').textContent=d.message;$('progress').value=d.progress;}if(d.type==='error'){setMode('setup');$('notice').textContent=d.message;$('run').disabled=false;}if(d.type==='result'){loadRun(d.run);$('notice').textContent='Not saved yet. Review the result, save it, or watch how it grew.';}};worker.onerror=e=>{setMode('setup');$('notice').textContent='Simulation stopped: '+e.message;};}
function setMode(m){mode=m;document.body.dataset.simulationMode=m;window.RanchView?.changed();for(const id of ['setup','running','result','playback'])$(id).hidden=id!==m;if(m!=='playback')playing=false;}
function territory(fresh=false){if(fresh)seed=(seed+1)>>>0||1;run=null;selection=null;document.getElementById('units').hidden=true;document.getElementById('unit-list').replaceChildren();document.getElementById('planner-note').textContent='';$('selection').hidden=true;workerStart();setMode('setup');$('run').disabled=true;$('new').disabled=true;$('seed').textContent='TERRITORY '+seed;$('objective').textContent=`Build shelters and sustain ${$('size').value==='large'?32:16} animals. Feasibility checked on run.`;$('title').textContent='A place to begin.';$('subtitle').textContent='Reroll the land before running the simulation.';$('notice').textContent='Shaping the territory…';history.replaceState(null,'',`/simulation?seed=${seed}&size=${$('size').value}`);worker.postMessage({type:'territory',seed,size:$('size').value});}
function land(){svg.replaceChildren();artDefs();const size=world.bounds.width;el('rect',{x:0,y:-size,width:size,height:size,fill:'#dce1bd'});terrainArtwork();const points=world.water.brook.centerline.map(p=>`${p[0]},${-p[1]}`).join(' ');for(const [stroke,width]of [['#7f9f75',18],['#b5cfc3',13],['#dbe6d4',6]])el('polyline',{points,fill:'none',stroke,'stroke-width':width,'stroke-linecap':'round','stroke-linejoin':'round'});for(const t of [...world.vegetation].sort((a,b)=>b.position[1]-a.position[1]))tree({...t,radius:(t.radius||2)*2.5});dynamic=el('g');window.dispatchEvent(new CustomEvent('simulation-land',{detail:{world,svg}}));fit();}
function fit(){const size=world?.bounds.width||540;view=[-size*.05,-size*1.05,size*1.1,size*1.1];setView();}
function setView(){window.RanchView?.changed();svg.setAttribute('viewBox',view.join(' '));draw();}
function zoom(k){const [x,y,w,h]=view;view=[x+w*(1-k)/2,y+h*(1-k)/2,w*k,h*k];setView();}
function floorIndex(list,t){let l=0,r=list.length-1,answer=0;while(l<=r){const mid=(l+r)>>1;if(list[mid].seconds<=t){answer=mid;l=mid+1;}else r=mid-1;}return answer;}
function along(points,t,fallback){if(!points?.length||t<points[0].seconds||t>points.at(-1).seconds)return fallback;for(let i=1;i<points.length;i++){const a=points[i-1],b=points[i];if(t<=b.seconds){const f=(t-a.seconds)/(b.seconds-a.seconds||1);return a.position.map((v,j)=>v+(b.position[j]-v)*f);}}return fallback;}
function currentFrame(){return run?.frames[floorIndex(run.frames,time)];}
function draw(){if(!dynamic)return;dynamic.replaceChildren();if(!run)return;const f=currentFrame(),unit=view[2]/Math.max(300,svg.clientWidth),radius=Math.max(3,unit*8);
 for(const t of f.trails)el('line',{x1:t.from[0],y1:-t.from[2],x2:t.to[0],y2:-t.to[2],stroke:'#b7a779','stroke-width':Math.max(1,t.width*2),opacity:.2+t.strength*.6},dynamic);
 for(const b of f.buildings){const q=b.footprint;if(!q)continue;el('rect',{x:q.x,y:-q.z-q.depth,width:q.width,height:q.depth,fill:b.progress===1?'#af7860':b.progress>0?'#d6b98b':'none',stroke:'#5e6650','stroke-width':unit,'stroke-dasharray':b.progress===1?'none':`${unit*3} ${unit*2}`,opacity:.4+b.progress*.6},dynamic);if(b.progress>0&&b.progress<1)el('rect',{x:q.x,y:-q.z-q.depth-3,width:q.width*b.progress,height:2,fill:'#506d48'},dynamic);}
 const actors=[];
 for(const w of f.workers){const list=tracks[w.id]||[],i=floorIndex(list,time),v=list[i];let actor=v&&v.seconds<=time?{...w,...v}:w;const next=list[i+1]||list[i];actor={...actor,position:along(next?.motion,time,actor.position),kind:'worker',color:w.id==='marley'?'#b98a42':'#31596a'};actors.push(actor);}
 const nextFrame=run.frames[Math.min(run.frames.length-1,floorIndex(run.frames,time)+1)];for(const a of f.animals){const motion=nextFrame.animals.find(r=>r.id===a.id)?.motion,p=along(motion,time,[a.position[0],a.position[2]]);actors.push({...a,position:[p[0],a.position[1],p[1]],kind:'animal',color:{horse:'#915d45',cow:'#625b58',goat:'#b49354',chicken:'#c98b35'}[a.species]||'#8b765c'});}
 const occupied={};for(const a of actors){const key=a.position[0].toFixed(1)+','+a.position[2].toFixed(1),i=occupied[key]||0;occupied[key]=i+1;const display=[a.position[0]+(i?Math.cos(i*2.4)*radius*2:0),a.position[2]+(i?Math.sin(i*2.4)*radius*2:0)];const c=el('circle',{cx:display[0],cy:-display[1],r:a.kind==='worker'?radius:radius*.8,fill:a.color,stroke:'#fff9e8','stroke-width':unit*1.4,'data-actor':a.id,tabindex:'0',role:'button','aria-label':a.name},dynamic);const show=()=>{selection=a.id;$('selection').hidden=false;$('selection').textContent=`${a.name} · ${a.activity}${a.cargo?' · carrying '+a.cargo.toFixed(1)+' '+a.material:''}`;};c.onpointerdown=show;c.onclick=show;c.onkeydown=e=>{if(e.key==='Enter'||e.key===' ')show();};if(selection===a.id){el('circle',{cx:display[0],cy:-display[1],r:radius*1.8,fill:'none',stroke:'#d19a37','stroke-width':unit},dynamic);}}
 $('units').hidden=false;const list=$('unit-list');for(const a of actors){let button=list.querySelector(`[data-unit="${a.id}"]`);if(!button){button=document.createElement('button');button.dataset.unit=a.id;list.append(button);}button.textContent=`${a.kind==='worker'?'●':'◆'} ${a.name} · ${a.activity}`;button.onclick=()=>{selection=a.id;view=[a.position[0]-65,-a.position[2]-65,130,130];$('selection').hidden=false;$('selection').textContent=`${a.name} · ${a.activity}`;setView();};}for(const b of list.children)if(!actors.some(a=>a.id===b.dataset.unit))b.remove();
 window.dispatchEvent(new CustomEvent('simulation-frame',{detail:{frame:f,actors,time,selection,run}}));
 $('planner-note').textContent=f.planner?.lastDecision?`Daddy · ${f.planner.lastDecision.reason}`:f.planner?'Daddy will review the farm at the start of the workday.':'';
 $('clock').textContent=`Day ${Math.floor(time/86400)+1} · ${String(Math.floor(time%86400/3600)).padStart(2,'0')}:${String(Math.floor(time%3600/60)).padStart(2,'0')} / ${Math.round(run.duration/86400)} simulated days`;$('scrub').value=time;
}
function loadRun(value){run=value;world=value.world;seed=value.seed;tracks={};for(const t of value.tracks)(tracks[t.id]||=([])).push(t);land();time=value.duration;setMode('result');$('title').textContent=value.paused?'Care needs attention.':'A ranch, grown together.';$('subtitle').textContent=`${value.sizeLabel} · Territory ${seed} · ${Math.round(value.duration/86400)} simulated days`;$('result-title').textContent=value.paused?'Safely paused':'Simulation concluded';$('summary').textContent=`${value.summary.completed}/${value.summary.total} structures built · ${value.summary.animals}/${value.objective.animals} animals · ${value.summary.care} care deliveries.`;$('save').disabled=false;$('save').textContent='Save';$('scrub').max=value.duration;draw();}
function db(){return new Promise((resolve,reject)=>{const q=indexedDB.open('ranch-simulations',1);q.onupgradeneeded=()=>q.result.createObjectStore('runs',{keyPath:'id'});q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});}
async function store(action,value){const database=await db();return new Promise((resolve,reject)=>{const tx=database.transaction('runs',action==='getAll'?'readonly':'readwrite'),q=tx.objectStore('runs')[action](value);tx.oncomplete=()=>{database.close();resolve(q.result);};tx.onerror=()=>{database.close();reject(tx.error);};tx.onabort=()=>reject(tx.error);});}
$('new').onclick=()=>territory(true);$('size').onchange=()=>territory();$('run').onclick=()=>{setMode('running');$('notice').textContent='Computing here on your device. Playback speed does not affect this wait.';$('progress').value=0;worker.postMessage({type:'run',seed,size:$('size').value});};$('cancel').onclick=()=>territory();$('discard').onclick=()=>{territory();$('notice').textContent='Unsaved result discarded. Saved copies are unchanged.';};
$('save').onclick=async()=>{try{$('save').disabled=true;await store('put',run);$('save').textContent='Saved ✓';$('notice').textContent='Saved on this device.';}catch(e){$('save').disabled=false;$('notice').textContent='Could not save: '+e.message;}};
$('watch').onclick=()=>{time=Math.max(0,(run.tracks.find(t=>!['resting','waiting-for-work-or-materials'].includes(t.activity))?.seconds||0)-10);setMode('playback');playing=true;$('play').textContent='Pause';$('notice').textContent='Follow the family as they build and care for the animals. Intent bubbles explain their tasks.';draw();};$('play').onclick=()=>{if(time>=run.duration)time=0;playing=!playing;$('play').textContent=playing?'Pause':'Play';};$('scrub').oninput=()=>{time=Number($('scrub').value);playing=false;$('play').textContent='Play';draw();};$('end').onclick=()=>{time=run.duration;setMode('result');draw();};
$('library').onclick=async()=>{const list=$('saved-list');list.replaceChildren();$('saved').showModal();try{const runs=await store('getAll');if(!runs.length)list.textContent='No saved runs yet.';for(const r of runs.sort((a,b)=>b.created.localeCompare(a.created))){const article=document.createElement('article'),text=document.createElement('span');text.textContent=`${r.sizeLabel} · Territory ${r.seed} · ${r.summary.animals} animals`;article.append(text);const open=document.createElement('button');open.textContent='Open';open.onclick=()=>{worker?.terminate();loadRun(r);$('saved').close();$('save').disabled=true;$('save').textContent='Saved ✓';$('notice').textContent='Loaded from this device.';};const remove=document.createElement('button');remove.textContent='Delete';remove.onclick=async()=>{try{await store('delete',r.id);article.remove();}catch(e){$('notice').textContent=e.message;}};article.append(open,remove);list.append(article);}}catch(e){list.textContent='Saved runs unavailable: '+e.message;}};$('close-saved').onclick=()=>$('saved').close();
$('zoom-in').onclick=()=>zoom(.7);$('zoom-out').onclick=()=>zoom(1.4);$('fit').onclick=fit;$('ranch-view').onclick=()=>{const f=currentFrame();if(!f)return;const p=f.buildings.map(b=>b.workPosition),xs=p.map(p=>p[0]),zs=p.map(p=>p[2]),w=Math.max(150,Math.max(...xs)-Math.min(...xs)+70);view=[Math.min(...xs)-35,-Math.max(...zs)-35,w,w];setView();};
let drag;svg.addEventListener('pointerdown',e=>{if(e.target.hasAttribute('data-actor'))return;drag={x:e.clientX,y:e.clientY,v:[...view]};svg.setPointerCapture(e.pointerId);});svg.addEventListener('pointermove',e=>{if(!drag)return;const scale=view[2]/Math.min(svg.clientWidth,svg.clientHeight);view=[drag.v[0]-(e.clientX-drag.x)*scale,drag.v[1]-(e.clientY-drag.y)*scale,drag.v[2],drag.v[3]];setView();});svg.addEventListener('pointerup',()=>drag=null);svg.addEventListener('pointercancel',()=>drag=null);
svg.addEventListener('wheel',e=>{e.preventDefault();const point=new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse()),factor=Math.exp(Math.max(-200,Math.min(200,e.deltaY))*.002),width=Math.max(35,Math.min((world?.bounds.width||540)*3,view[2]*factor)),ratio=width/view[2];view=[point.x+(view[0]-point.x)*ratio,point.y+(view[1]-point.y)*ratio,width,view[3]*ratio];setView();},{passive:false});
function animate(now){if(playing&&run){time=Math.min(run.duration,time+Math.min(.1,(now-lastTime)/1000)*Number($('speed').value));draw();if(time>=run.duration){playing=false;$('play').textContent='Replay';}}lastTime=now;requestAnimationFrame(animate);}requestAnimationFrame(animate);
window.RanchView?.register('simulation',()=>({seed,size:run?.sizeLabel||$('size').value,mode,playing,seconds:time,duration:run?.duration,summary:run?.summary,view,selection}));
$('size').value=new URLSearchParams(location.search).get('size')==='large'?'large':'small';territory();





window.SimulationPlayback={getState:()=>({world,run,frame:currentFrame(),time}),select:(id)=>{selection=id;draw();},redraw:draw};
